// Existing entry points: install and doctor.
// Proposed appd consumers: status, start and stop.
// Dashboard is a future consumer of the same service surface.

// Entry point reached by the OS service manager.
// Acquires the single-instance lock, then runs until stopped.
// It does not call StartAsync again.

public interface IDaemonService
{
    bool IsRunning();
    Task StartAsync(CancellationToken ct);
    Task StopAsync(CancellationToken ct);
}

public interface IAutostartEntryService
{
    Task<AutostartEntryState> InspectAsync(CancellationToken ct);
    Task SetEnabledAsync(bool enabled, CancellationToken ct);
}

// AutostartEntryState: result shape is still unwritten.
// It needs existence, enabled state and actionable diagnosis.
// Retry/log settings are not silently hidden in a DTO.
// Their operations follow the policy decision.

// StartAsync:
//   probe lock -> inspect entry if needed -> OS start -> observe lock
// StopAsync:
//   probe lock -> OS stop -> observe lock released
// No arbitrary executable, command or lock path comes from callers.
// Timeout values and failure result contracts are undecided.

// Reuse ISetupCondition for install and doctor.
// One AutostartEntryCondition owns checking/repairing setup.
// AutostartEntryService exposes user configuration.
// Both call the same platform entry adapter.
// Existing Detect/Repair are synchronous; proposed platform I/O
// is asynchronous. Their integration is unresolved, not hidden.

// TryAcquire -> hold lease -> one cancellation-linked await
// Stop releases the lease when the process exits.
// Stop signalling and shutdown lifetime still need a mechanism.
// Duplicate acquisition never becomes a second daemon.

public interface IPlatformServices
{
    IPlatformFileSystem FileSystem { get; }
    IPresenceCheck Presence { get; }
    IPlatformDaemon Daemon { get; } // Proposed
}

public interface IPlatformDaemon
{
    ISingleInstanceLock Lock { get; }
    IDaemonProcessControl Process { get; }
    IAutostartEntry AutostartEntry { get; }
}

public interface ISingleInstanceLock
{
    bool IsHeld(ISystemServices services);
    IDisposable? TryAcquire(ISystemServices services);
}

// Proposed: null means another instance owns the lock.
// A returned lease is held for the daemon lifetime.
// All other failures remain distinguishable from contention.

public interface IDaemonProcessControl
{
    Task StartAsync(ISystemServices services, CancellationToken ct);
    Task StopAsync(ISystemServices services, CancellationToken ct);
}

// Only the appd entry belonging to the current user/scope.
// No command, executable, PID or target-session argument.

public interface IAutostartEntry
{
    Task<AutostartEntryState> InspectAsync(
        ISystemServices services, CancellationToken ct);
    Task ApplyAsync(AutostartEntryDefinition definition,
        ISystemServices services, CancellationToken ct);
    Task RemoveAsync(ISystemServices services, CancellationToken ct);
}

// AutostartEntryDefinition is unwritten pending policy approval.
// It must carry the existing MachinePaths-owned launcher path.
// It must not become an arbitrary-command escape hatch.

// Proposed addition to the existing IPlatformFileSystem:
void EnsurePrivateDirectory(string path);

// POSIX: create or verify the lock directory is private.
// Windows: the lock uses a named mutex, not this directory.
// Decide whether this method is POSIX-only or provides
// equivalent private-directory behavior on Windows too.

// Lock: exclusive FileStream in the approved runtime directory.
// Start: launchctl bootstrap if absent, then kickstart (no -k).
// Stop candidate: bootout this user's loaded appd job.
// Entry: LaunchAgent plist read by launchd.
// Command runner is shared with Linux; no duplicate Process owner.

// Lock: exclusive FileStream under XDG_RUNTIME_DIR.
// Start/stop: systemctl --user start/stop agentguard-appd.service.
// Entry enable/disable: unit install links, never mask.
// Shared Process adapter runs systemctl.
// Desktop connection mechanism is still undecided.

// Lock: Local\ named mutex, scoped to the logon session.
// Task: \AgentGuard\appd-<user SID>.
// Start candidate: IRegisteredTask.RunEx with caller session ID.
// Stop candidate: IRunningTask.Stop on the matching instance.
// Task permits Parallel; the mutex refuses same-session duplicates.
// Exact instance-to-session selection is still unwritten.

internal interface IProcessFactory
{
    IProcess Create();
    IProcess GetCurrentProcess();
    IProcess GetProcessById(int processId);
}

internal interface IProcess : IDisposable
{
    IProcessStartInfo StartInfo { get; }
    int Id { get; }
    int SessionId { get; }
    bool HasExited { get; }
    int ExitCode { get; }
    ITextReader StandardOutput { get; }
    ITextReader StandardError { get; }

    bool Start();
    Task WaitForExitAsync(CancellationToken cancellationToken);
    void Kill(bool entireProcessTree);
}

internal interface IProcessStartInfo
{
    string FileName { get; set; }
    Collection<string> ArgumentList { get; }
    string WorkingDirectory { get; set; }
    bool UseShellExecute { get; set; }
    bool RedirectStandardOutput { get; set; }
    bool RedirectStandardError { get; set; }
    bool CreateNoWindow { get; set; }
    Encoding? StandardOutputEncoding { get; set; }
    Encoding? StandardErrorEncoding { get; set; }
}

internal interface IFileStreamFactory
{
    IFileStream Create(
        string path,
        FileMode mode,
        FileAccess access,
        FileShare share);
}

internal interface IFileStream : IDisposable
{
}

internal interface IMutexFactory
{
    IMutex Create(bool initiallyOwned, string name, out bool createdNew);
    bool TryOpenExisting(string name, [NotNullWhen(true)] out IMutex? result);
}

internal interface IMutex : IDisposable
{
    bool WaitOne(int millisecondsTimeout);
    void ReleaseMutex();
}

internal interface ITaskServiceFactory
{
    ITaskService Create();
}

internal interface ITaskService : IDisposable
{
    void Connect();
    ITaskFolder GetFolder(string path);
}

internal interface ITaskFolder : IDisposable
{
    ITaskFolder CreateFolder(string subFolderName, string? sddl);
    IRegisteredTask GetTask(string path);
    IRegisteredTask RegisterTask(
        string path,
        string xmlText,
        int flags,
        string? userId,
        string? password,
        int logonType,
        string? sddl);
    void DeleteTask(string name, int flags);
}

internal interface IRegisteredTask : IDisposable
{
    string Path { get; }
    string Xml { get; }
    bool Enabled { get; }
    IRunningTask RunEx(
        string[]? parameters,
        int flags,
        int sessionId,
        string? user);
    IRunningTaskCollection GetInstances(int flags);
}

internal interface IRunningTaskCollection : IDisposable
{
    int Count { get; }
    IRunningTask this[int index] { get; }
}

internal interface IRunningTask : IDisposable
{
    string Path { get; }
    string InstanceGuid { get; }
    uint EnginePID { get; }
    void Refresh();
    void Stop();
}

internal interface IAssemblyResources
{
    IReadStream? GetManifestResourceStream(string name);
}

internal interface IReadStream : IDisposable
{
    int Read(byte[] buffer, int offset, int count);
}

internal interface ITextReader : IDisposable
{
    string ReadToEnd();
    Task<string> ReadToEndAsync(CancellationToken cancellationToken);
}

internal interface IStreamReaderFactory
{
    ITextReader Create(
        IReadStream stream,
        Encoding encoding,
        bool detectEncodingFromByteOrderMarks,
        int bufferSize,
        bool leaveOpen);
}

internal interface IReadStreamBridgeFactory
{
    IReadStreamBridge Create(IReadStream stream, bool leaveOpen);
}

internal interface IReadStreamBridge : IReadStream
{
    bool CanRead { get; }
    bool CanSeek { get; }
    bool CanWrite { get; }
    long Length { get; }
    long Position { get; set; }
    void Flush();
    long Seek(long offset, SeekOrigin origin);
    void SetLength(long value);
    void Write(byte[] buffer, int offset, int count);
}

internal interface IWindowsIdentityFactory
{
    IWindowsIdentity GetCurrent();
}

internal interface IWindowsIdentity : IDisposable
{
    ISecurityIdentifier? User { get; }
}

internal interface ISecurityIdentifier
{
    string Value { get; }
}
